import Complex64Array = require( '@stdlib/array/complex64' );
import icamax = require( './index' );


// TESTS //

// The function returns a number...
{
	const cx = new Complex64Array( 10 );

	icamax( cx.length, cx, 1 ); // $ExpectType number
}

// The compiler throws an error if the function is provided a first argument which is not a number...
{
	const cx = new Complex64Array( 10 );

	icamax( '10', cx, 1 ); // $ExpectError
	icamax( true, cx, 1 ); // $ExpectError
	icamax( false, cx, 1 ); // $ExpectError
	icamax( null, cx, 1 ); // $ExpectError
	icamax( undefined, cx, 1 ); // $ExpectError
	icamax( [], cx, 1 ); // $ExpectError
	icamax( {}, cx, 1 ); // $ExpectError
	icamax( ( x: number ): number => x, cx, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a Complex64Array...
{
	const cx = new Complex64Array( 10 );

	icamax( cx.length, 10, 1 ); // $ExpectError
	icamax( cx.length, '10', 1 ); // $ExpectError
	icamax( cx.length, true, 1 ); // $ExpectError
	icamax( cx.length, false, 1 ); // $ExpectError
	icamax( cx.length, null, 1 ); // $ExpectError
	icamax( cx.length, undefined, 1 ); // $ExpectError
	icamax( cx.length, [], 1 ); // $ExpectError
	icamax( cx.length, {}, 1 ); // $ExpectError
	icamax( cx.length, ( cx: number ): number => cx, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a third argument which is not a number...
{
	const cx = new Complex64Array( 10 );

	icamax( cx.length, cx, '10' ); // $ExpectError
	icamax( cx.length, cx, true ); // $ExpectError
	icamax( cx.length, cx, false ); // $ExpectError
	icamax( cx.length, cx, null ); // $ExpectError
	icamax( cx.length, cx, undefined ); // $ExpectError
	icamax( cx.length, cx, [] ); // $ExpectError
	icamax( cx.length, cx, {} ); // $ExpectError
	icamax( cx.length, cx, ( cx: number ): number => cx ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const cx = new Complex64Array( 10 );

	icamax(); // $ExpectError
	icamax( cx.length ); // $ExpectError
	icamax( cx.length, cx ); // $ExpectError
	icamax( cx.length, cx, 1, 10 ); // $ExpectError
}

// Attached to main export is an `ndarray` method which returns a number...
{
	const cx = new Complex64Array( 10 );

	icamax.ndarray( cx.length, cx, 1, 0 ); // $ExpectType number
}

// The compiler throws an error if the `ndarray` method is provided a first argument which is not a number...
{
	const cx = new Complex64Array( 10 );

	icamax.ndarray( '10', cx, 1, 0 ); // $ExpectError
	icamax.ndarray( true, cx, 1, 0 ); // $ExpectError
	icamax.ndarray( false, cx, 1, 0 ); // $ExpectError
	icamax.ndarray( null, cx, 1, 0 ); // $ExpectError
	icamax.ndarray( undefined, cx, 1, 0 ); // $ExpectError
	icamax.ndarray( [], cx, 1, 0 ); // $ExpectError
	icamax.ndarray( {}, cx, 1, 0 ); // $ExpectError
	icamax.ndarray( ( cx: number ): number => cx, cx, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a second argument which is not a Complex64Array...
{
	const cx = new Complex64Array( 10 );

	icamax.ndarray( cx.length, 10, 1, 0 ); // $ExpectError
	icamax.ndarray( cx.length, '10', 1, 0 ); // $ExpectError
	icamax.ndarray( cx.length, true, 1, 0 ); // $ExpectError
	icamax.ndarray( cx.length, false, 1, 0 ); // $ExpectError
	icamax.ndarray( cx.length, null, 1, 0 ); // $ExpectError
	icamax.ndarray( cx.length, undefined, 1, 0 ); // $ExpectError
	icamax.ndarray( cx.length, [], 1, 0 ); // $ExpectError
	icamax.ndarray( cx.length, {}, 1, 0 ); // $ExpectError
	icamax.ndarray( cx.length, ( cx: number ): number => cx, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a third argument which is not a number...
{
	const cx = new Complex64Array( 10 );

	icamax.ndarray( cx.length, cx, '10', 0 ); // $ExpectError
	icamax.ndarray( cx.length, cx, true, 0 ); // $ExpectError
	icamax.ndarray( cx.length, cx, false, 0 ); // $ExpectError
	icamax.ndarray( cx.length, cx, null, 0 ); // $ExpectError
	icamax.ndarray( cx.length, cx, undefined, 0 ); // $ExpectError
	icamax.ndarray( cx.length, cx, [], 0 ); // $ExpectError
	icamax.ndarray( cx.length, cx, {}, 0 ); // $ExpectError
	icamax.ndarray( cx.length, cx, ( cx: number ): number => cx, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a fourth argument which is not a number...
{
	const cx = new Complex64Array( 10 );

	icamax.ndarray( cx.length, cx, 1, '10' ); // $ExpectError
	icamax.ndarray( cx.length, cx, 1, true ); // $ExpectError
	icamax.ndarray( cx.length, cx, 1, false ); // $ExpectError
	icamax.ndarray( cx.length, cx, 1, null ); // $ExpectError
	icamax.ndarray( cx.length, cx, 1, undefined ); // $ExpectError
	icamax.ndarray( cx.length, cx, 1, [] ); // $ExpectError
	icamax.ndarray( cx.length, cx, 1, {} ); // $ExpectError
	icamax.ndarray( cx.length, cx, 1, ( cx: number ): number => cx ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided an unsupported number of arguments...
{
	const cx = new Complex64Array( 10 );

	icamax.ndarray(); // $ExpectError
	icamax.ndarray( cx.length ); // $ExpectError
	icamax.ndarray( cx.length, cx ); // $ExpectError
	icamax.ndarray( cx.length, cx, 1 ); // $ExpectError
	icamax.ndarray( cx.length, cx, 1, 0, 10 ); // $ExpectError
}
